<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT v.*,c.nome cliente,u.nome usuario_nome FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id JOIN usuarios u ON u.id=v.usuario_id WHERE v.id=?");$st->execute([$id]);$v=$st->fetch();if(!$v)exit('Venda não encontrada.');$st=$pdo->prepare('SELECT vi.*,p.nome FROM venda_itens vi JOIN produtos p ON p.id=vi.produto_id WHERE vi.venda_id=?');$st->execute([$id]);$items=$st->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="no-print page-head"><div><h1>Comprovante</h1></div><div class="actions"><button class="btn primary" onclick="printPage()">Imprimir</button><a class="btn secondary" href="index.php">Novo atendimento</a></div></div><div class="card"><div class="print-header print-only"><h1><?=e(setting('nome_livraria',APP_NAME))?></h1><div class="print-small"><?=e(setting('endereco_livraria'))?> · <?=e(setting('telefone_livraria'))?></div></div><h2>Venda nº <?=e($v['numero'])?></h2><p><?=datetime_br($v['data_venda'])?> · Cliente: <?=e($v['cliente']?:'Consumidor não identificado')?></p><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['nome'])?></td><td><?=e($i['quantidade'])?></td><td><?=money($i['preco_unitario'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach; ?></tbody></table></div><div style="max-width:360px;margin:15px 0 0 auto"><div class="total-line"><span>Subtotal</span><strong><?=money($v['subtotal'])?></strong></div><div class="total-line"><span>Desconto</span><strong><?=money($v['desconto'])?></strong></div><div class="total-line total"><span>TOTAL</span><strong><?=money($v['total'])?></strong></div><div class="total-line"><span>Pagamento</span><strong><?=e($v['forma_pagamento'])?></strong></div><?php if($v['forma_pagamento']==='Crédito'): ?><div class="total-line"><span>Parcelas</span><strong><?=e($v['parcelas'])?>x</strong></div><?php endif; ?><div class="total-line"><span>Recebido</span><strong><?=money($v['valor_recebido'])?></strong></div><div class="total-line"><span>Troco</span><strong><?=money($v['troco'])?></strong></div><div class="total-line"><span>Usuário responsável</span><strong><?=e($v['usuario_nome'])?></strong></div></div><p class="muted">⚠ <?=e(setting('comprovante_dados'))?></p></div><?php include __DIR__.'/../../includes/footer.php'; ?>
